#include<bits/stdc++.h>
using namespace std;
int main(int argc,char**argv){int seed=argc>1?atoi(argv[1]):170501;mt19937 rng(seed);ifstream io("research/mixed_tier17_root_sums_20261105/cache/origin.bin",ios::binary|ios::ate);if(!io)return 2;int n=io.tellg();io.seekg(0);vector<uint8_t> origin(n),weight(n);io.read((char*)origin.data(),n);ifstream iw("research/mixed_tier17_root_sums_20261105/cache/weights.bin",ios::binary);iw.read((char*)weight.data(),n);if(!iw)return 2;ifstream ie("research/mixed_tier17_root_sums_20261105/cache/edges.bin",ios::binary|ios::ate);long long m=ie.tellg();if(m<0||m%8)return 2;m/=8;ie.seekg(0);vector<vector<int>> adj(n);for(long long k=0;k<m;k++){int a,b;ie.read((char*)&a,4);ie.read((char*)&b,4);if(a<0||a>=n||b<0||b>=n)return 3;adj[a].push_back(b);adj[b].push_back(a);}vector<uint8_t>sel(n);vector<int>cnt(n),block(n),tabu(n);int cur=0,best=0;for(int i=0;i<n;i++)if(origin[i])best+=weight[i];auto insert=[&](int i){sel[i]=1;cur+=weight[i];for(int j:adj[i]){cnt[j]++;block[j]+=weight[i];}};auto remove=[&](int i,vector<int>&zeros,int it){sel[i]=0;cur-=weight[i];tabu[i]=it+7+rng()%25;for(int j:adj[i]){cnt[j]--;block[j]-=weight[i];if(!sel[j]&&!cnt[j])zeros.push_back(j);}};auto reset=[&](){fill(sel.begin(),sel.end(),0);fill(cnt.begin(),cnt.end(),0);fill(block.begin(),block.end(),0);fill(tabu.begin(),tabu.end(),0);cur=0;for(int i=0;i<n;i++)if(origin[i]){if(cnt[i])return false;insert(i);}return true;};if(!reset())return 4;cout<<"vertices "<<n<<" edges "<<m<<" source "<<cur<<endl;
for(int it=1;it<=20000000;it++){int pick=-1,bc=99999;for(int t=0;t<512;t++){int q=rng()%n;if(sel[q]||tabu[q]>it)continue;int score=block[q]-weight[q]+(rng()%1000<70?int(rng()%5):0);if(score<bc){bc=score;pick=q;}}if(pick<0)continue;if(block[pick]>12&&rng()%100<(block[pick]<=40?70:block[pick]<=100?92:98))continue;vector<int>victims,zeros;for(int j:adj[pick])if(sel[j])victims.push_back(j);for(int j:victims)remove(j,zeros,it);insert(pick);shuffle(zeros.begin(),zeros.end(),rng);for(int j:zeros)if(!sel[j]&&!cnt[j]&&tabu[j]<=it)insert(j);if(cur>best){best=cur;cout<<"POTENTIAL "<<best<<" iteration "<<it<<endl;ofstream f("research/mixed_tier17_root_sums_20261105/cache/POTENTIAL.bin",ios::binary);f.write((char*)sel.data(),n);return 0;}if(cur<best-240)reset();if(it%100000==0)cout<<"progress "<<it<<" points "<<cur<<" best "<<best<<endl;}}
